sp_CriarCategoriaProduto	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_CriarCategoriaProduto`(\n\n    IN p_idEmpresa      INT,\n\n    IN p_nome           VARCHAR(70),\n\n    IN p_descricao      VARCHAR(50),\n\n    IN p_idCategoriaPai INT\n\n)\nBEGIN\n\n    INSERT INTO CategoriaProduto (Nome, Descricao, categoria_pai_id, fAtivo)\n\n    VALUES (p_nome, p_descricao, p_idCategoriaPai, 1);\n\n    SELECT LAST_INSERT_ID() AS idCategoria;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
